/* ═══════════════ HEAD TRACKING BY WEBCAM (2.13) ═══════════════
   What the large simulators do with TrackIR or a webcam (opentrack, AITrack): the head turns, the view turns
   with it, and both hands stay on the controls. The camera's picture never leaves the browser: MediaPipe's
   face detector (Google, Apache 2.0; the library about 10 MB from jsDelivr on the first start, the model,
   230 kB, inside this file) finds six points of the face 20 times a second, on the processor; from them:
     turn  the nose's place between the ears: t = (nose - ear1) / (ear2 - ear1), 0.5 facing the screen;
           with the ears ~8 cm either side and the nose ~10 cm ahead of them, t - 0.5 = 0.625 tan(turn)
     nod   the nose's place between the eyes and the mouth: u = (nose - eyes) / (mouth - eyes), changing
           by about 0.0055 per degree
   both against the pose at the start (or Z: centre), filtered (One Euro: still when the head is still, quick
   when it moves), with a dead zone of 2° and gains (3.5 for the turn: 20° of head, 63° of view; 2.5 for the
   nod). The view follows in the cockpit view; the glances (Q, E) and C take precedence. Shift+Z on / off. */
const HT={on:false,ok:false,busy:false,yaw:0,pitch:0,status:'off',hz:0,det:null,video:null,stream:null,cal:null,acc:[],lastT:0,lastVT:-1,lost:0,n:0,hzT:0,fy:null,fp:null,
  LIB:'https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.14'};
const HT_MODEL='';   // blaze_face_short_range.tflite (float16; MediaPipe's model card: Apache 2.0), sha256 b4578f35940bf5a1...
/* the head's turn and nod (radians) from the detector's six key points, against a calibration {t0,u0} */
function htPose(kp,cal){if(!kp||kp.length<6)return null;const nose=kp[2],e1=kp[0],e2=kp[1],m=kp[3],a=Math.min(kp[4].x,kp[5].x),b=Math.max(kp[4].x,kp[5].x);
  if(b-a<0.02)return null;const t=(nose.x-a)/(b-a),ey=(e1.y+e2.y)/2,du=m.y-ey;if(du<0.005)return null;const u=(nose.y-ey)/du;
  if(!cal)return {t,u};
  return {t,u,turn:Math.atan((t-cal.t0)/0.625),nod:(u-cal.u0)/0.0055*Math.PI/180};}
/* One Euro filter (Casiez et al. 2012) */
function htEuro(mc,beta){return {x:null,dx:0,f(v,dt){const a=c=>1/(1+1/(2*Math.PI*c*dt));if(this.x===null){this.x=v;return v;}const d=(v-this.x)/dt;this.dx+=(d-this.dx)*a(1);const c=mc+beta*Math.abs(this.dx);this.x+=(v-this.x)*a(c);return this.x;}};}
async function htStart(){if(HT.on||HT.busy)return;HT.busy=true;
  try{
    if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia)throw new Error('no camera access in this browser or page');
    HT.status='asking for the camera…';
    const st=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:320},height:{ideal:240},frameRate:{ideal:30},facingMode:'user'},audio:false});
    const v=document.createElement('video');v.muted=true;v.playsInline=true;v.srcObject=st;await v.play();HT.video=v;HT.stream=st;
    if(!HT.det){HT.status='loading the face detector (about 10 MB the first time)…';
      const tv=await import(HT.LIB+'/vision_bundle.mjs');const fs=await tv.FilesetResolver.forVisionTasks(HT.LIB+'/wasm');
      const bin=Uint8Array.from(atob(HT_MODEL),c=>c.charCodeAt(0));
      HT.det=await tv.FaceDetector.createFromOptions(fs,{baseOptions:{modelAssetBuffer:bin,delegate:'CPU'},runningMode:'VIDEO',minDetectionConfidence:0.5});}
    HT.on=true;HT.ok=false;HT.cal=null;HT.acc=[];HT.lost=0;HT.status='looking for the face… (look at the screen)';
  }catch(e){htStop();const emb=(()=>{try{return window.self!==window.top;}catch(_){return true;}})(),nm=e&&e.name||'';
    HT.status=(emb&&(nm==='NotAllowedError'||nm==='SecurityError'||!navigator.mediaDevices))?'the camera is not available inside an embedded page: open the page directly in the browser':
      nm==='NotAllowedError'?'the camera was not allowed (the browser\'s camera permission for this page)':nm==='NotFoundError'?'no camera found':'not started: '+String(e&&e.message||e).slice(0,120);}
  HT.busy=false;}
function htStop(){HT.on=false;HT.ok=false;HT.yaw=0;HT.pitch=0;if(HT.stream)HT.stream.getTracks().forEach(t=>t.stop());HT.stream=null;HT.video=null;HT.status='off';}
function htCentre(){if(!HT.on)return;HT.cal=null;HT.acc=[];HT.status='centring… (look at the screen)';}
function htStep(dt){if(!HT.on||!HT.det||!HT.video)return;const now=performance.now(),v=HT.video;
  if(now-HT.lastT<45||v.readyState<2||v.currentTime===HT.lastVT)return;
  const dtS=Math.min(0.2,Math.max(0.02,(now-HT.lastT)/1000));HT.lastT=now;HT.lastVT=v.currentTime;
  let r=null;try{r=HT.det.detectForVideo(v,now);}catch(e){htStop();HT.status='detector stopped: '+String(e&&e.message||e).slice(0,80);return;}
  HT.n++;if(now-HT.hzT>1000){HT.hz=HT.n*1000/(now-HT.hzT||1000);HT.n=0;HT.hzT=now;}
  const d=r&&r.detections&&r.detections[0],p=d?htPose(d.keypoints,HT.cal):null;
  if(!p){if(++HT.lost>10){HT.ok=false;if(HT.cal)HT.status='no face in the picture';}return;}
  HT.lost=0;
  if(!HT.cal){HT.acc.push(p);if(HT.acc.length>=12){const m=k=>HT.acc.reduce((s,q)=>s+q[k],0)/HT.acc.length;HT.cal={t0:m('t'),u0:m('u')};HT.fy=htEuro(0.8,0.6);HT.fp=htEuro(0.8,0.6);}return;}
  const D=Math.PI/180,dz=2*D,g=(x,G)=>Math.sign(x)*Math.max(0,Math.abs(x)-dz)*G;
  const turn=HT.fy.f(p.turn,dtS),nod=HT.fp.f(p.nod,dtS);
  HT.yaw=clamp(-g(turn,cfg.htYaw||3.5),-150*D,150*D);   // turning to one's left moves the nose toward the ear on the picture's right: the view turns left
  HT.pitch=clamp(-g(nod,cfg.htPitch||2.5),-60*D,40*D);  // a nod down brings the nose nearer the mouth: the view goes down
  HT.ok=true;HT.status=`running · ${Math.round(HT.hz)} Hz · head ${Math.round(turn/D)}° / ${Math.round(nod/D)}°`;}
